import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        // The minimum difference can only occur between neighbours in sorted order.
        long delta = Long.MAX_VALUE;
        for (int i = 0; i + 1 < n; i++) delta = Math.min(delta, a[i + 1] - a[i]);
        StringBuilder body = new StringBuilder();
        int count = 0;
        for (int i = 0; i + 1 < n; i++)
            if (a[i + 1] - a[i] == delta) {
                count++;
                body.append(a[i]).append(' ').append(a[i + 1]).append('\n');
            }
        System.out.print(count + "\n" + body);
    }
}

package main

import (
	"io"
	"math"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	slices.Sort(a)
	// The minimum difference can only occur between neighbours in sorted order.
	delta := int64(math.MaxInt64)
	for i := 0; i+1 < n; i++ {
		delta = min(delta, a[i+1]-a[i])
	}
	var body []byte
	count := 0
	for i := 0; i+1 < n; i++ {
		if a[i+1]-a[i] == delta {
			count++
			body = strconv.AppendInt(body, a[i], 10)
			body = append(body, ' ')
			body = strconv.AppendInt(body, a[i+1], 10)
			body = append(body, '\n')
		}
	}
	out := strconv.AppendInt(nil, int64(count), 10)
	out = append(out, '\n')
	os.Stdout.Write(append(out, body...))
}
